// SPDX-License-Identifier: AGPL-3.0-only
//! The cluster coordinator's membership API is authenticated (ADR-0011): a
//! network-reachable coordinator cannot be reshaped by an unauthenticated caller.
//! Reads (`/cluster/map`, `/cluster/health`) require any valid key; the mutating
//! shard ops require the `admin` role; `/healthz` and `/readyz` stay open. With no
//! keys configured (insecure mode) any caller is admitted — covered by the other
//! cluster tests, which run keyless.

// A test harness; panics are the failure signal (ADR-0017 scopes the
// unwrap/expect ban to non-test code).
#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::time::Duration;

use quiver_server::{Action, ApiKey, CollectionScope, Config, serve};
use tokio::net::TcpListener;

async fn wait_ready(http: &reqwest::Client, base: &str) {
    for _ in 0..200 {
        if let Ok(resp) = http.get(format!("{base}/healthz")).send().await
            && resp.status().is_success()
        {
            return;
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
    panic!("coordinator did not become ready");
}

#[tokio::test]
async fn coordinator_membership_api_requires_auth() {
    let admin = "admin-secret";
    let reader = "reader-secret";

    let rest_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let grpc_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let rest_addr = rest_listener.local_addr().unwrap();
    let grpc_addr = grpc_listener.local_addr().unwrap();

    let config = Config {
        rest_addr,
        grpc_addr,
        coordinator: true,
        // A shard to remove and a read-only key alongside the admin key.
        cluster_shards: vec!["http://127.0.0.1:1".into(), "http://127.0.0.1:2".into()],
        api_keys: vec![
            ApiKey::admin(admin),
            ApiKey {
                secret: reader.to_owned(),
                role: Action::Read,
                collections: CollectionScope::All,
                id: None,
            },
        ],
        ..Default::default()
    };
    let server = tokio::spawn(async move {
        let _ = serve(config, rest_listener, grpc_listener).await;
    });

    let http = reqwest::Client::new();
    let base = format!("http://{rest_addr}");
    wait_ready(&http, &base).await;

    // /healthz is open (liveness) even with keys configured.
    let h = http.get(format!("{base}/healthz")).send().await.unwrap();
    assert_eq!(
        h.status(),
        reqwest::StatusCode::OK,
        "healthz must stay open"
    );

    // --- A mutating op (add a shard) ---
    let add_body = serde_json::json!({"primary_url": "http://127.0.0.1:3", "replica_urls": []});

    // No bearer -> 401.
    let no_key = http
        .post(format!("{base}/cluster/shards"))
        .json(&add_body)
        .send()
        .await
        .unwrap();
    assert_eq!(
        no_key.status(),
        reqwest::StatusCode::UNAUTHORIZED,
        "add_shard without a key must be 401"
    );

    // Read-only key -> 403 (authenticated but role too low for a mutation).
    let ro = http
        .post(format!("{base}/cluster/shards"))
        .bearer_auth(reader)
        .json(&add_body)
        .send()
        .await
        .unwrap();
    assert_eq!(
        ro.status(),
        reqwest::StatusCode::FORBIDDEN,
        "add_shard with a read-only key must be 403"
    );

    // Admin key -> 200, and the shard is added.
    let ok = http
        .post(format!("{base}/cluster/shards"))
        .bearer_auth(admin)
        .json(&add_body)
        .send()
        .await
        .unwrap();
    assert_eq!(
        ok.status(),
        reqwest::StatusCode::OK,
        "add_shard with the admin key must succeed"
    );
    let map: serde_json::Value = ok.json().await.unwrap();
    assert_eq!(map["shards"].as_array().unwrap().len(), 3);

    // --- DELETE is admin-gated too: no key -> 401 ---
    let del_no_key = http
        .delete(format!("{base}/cluster/shards/2"))
        .send()
        .await
        .unwrap();
    assert_eq!(
        del_no_key.status(),
        reqwest::StatusCode::UNAUTHORIZED,
        "remove_shard without a key must be 401"
    );

    // --- A read op (/cluster/map): no key -> 401, read-only key -> 200 ---
    let map_no_key = http
        .get(format!("{base}/cluster/map"))
        .send()
        .await
        .unwrap();
    assert_eq!(
        map_no_key.status(),
        reqwest::StatusCode::UNAUTHORIZED,
        "/cluster/map without a key must be 401"
    );
    let map_ro = http
        .get(format!("{base}/cluster/map"))
        .bearer_auth(reader)
        .send()
        .await
        .unwrap();
    assert_eq!(
        map_ro.status(),
        reqwest::StatusCode::OK,
        "/cluster/map with a read-only key must succeed"
    );

    server.abort();
}

// SPDX-License-Identifier: AGPL-3.0-only
//! Every response carries the baseline security headers flagged by the v0.29.0
//! OWASP ZAP scan — on the open endpoints and the authed API alike.
#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::time::Duration;

use quiver_server::{Config, serve};
use tokio::net::TcpListener;

async fn wait_ready(http: &reqwest::Client, base: &str) {
    for _ in 0..200 {
        if let Ok(resp) = http.get(format!("{base}/healthz")).send().await
            && resp.status().is_success()
        {
            return;
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
    panic!("server did not become ready");
}

fn assert_security_headers(headers: &reqwest::header::HeaderMap, label: &str) {
    assert_eq!(
        headers.get("x-content-type-options").map(|v| v.as_bytes()),
        Some(&b"nosniff"[..]),
        "{label}: missing x-content-type-options: nosniff"
    );
    assert_eq!(
        headers
            .get("cross-origin-resource-policy")
            .map(|v| v.as_bytes()),
        Some(&b"same-origin"[..]),
        "{label}: missing cross-origin-resource-policy"
    );
}

#[tokio::test]
async fn every_response_carries_security_headers() {
    let tmp = tempfile::tempdir().unwrap();
    let key = "test-api-key";

    let rest_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let grpc_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let rest_addr = rest_listener.local_addr().unwrap();
    let grpc_addr = grpc_listener.local_addr().unwrap();

    let config = Config {
        data_dir: tmp.path().to_path_buf(),
        rest_addr,
        grpc_addr,
        api_keys: vec![key.into()],
        encryption_key: Some(
            "00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff".to_owned(),
        ),
        ..Default::default()
    };
    let server = tokio::spawn(async move {
        let _ = serve(config, rest_listener, grpc_listener).await;
    });

    let http = reqwest::Client::new();
    let base = format!("http://{rest_addr}");
    wait_ready(&http, &base).await;

    // Open endpoint.
    let h = http.get(format!("{base}/healthz")).send().await.unwrap();
    assert_security_headers(h.headers(), "/healthz");

    // Authed API — a 401 (no key) must still carry the headers.
    let unauth = http
        .get(format!("{base}/v1/collections"))
        .send()
        .await
        .unwrap();
    assert_eq!(unauth.status(), reqwest::StatusCode::UNAUTHORIZED);
    assert_security_headers(unauth.headers(), "/v1/collections 401");

    // Authed API — a 200 response.
    let ok = http
        .get(format!("{base}/v1/collections"))
        .bearer_auth(key)
        .send()
        .await
        .unwrap();
    assert_eq!(ok.status(), reqwest::StatusCode::OK);
    assert_security_headers(ok.headers(), "/v1/collections 200");

    server.abort();
}

// SPDX-License-Identifier: AGPL-3.0-only
//! Role-based access control end-to-end (ADR-0011): prove that scoped API keys
//! are **default-deny** — an over-privileged action and a cross-namespace
//! access are both refused (HTTP 403 / gRPC `PermissionDenied`) — while in-scope
//! requests succeed, and that listing never reveals out-of-scope collections.
//! Enforcement lives at the engine-facing op layer, so both transports honour
//! it; this test exercises REST for the full matrix and gRPC for one denial.
//!
//! Integration-test helpers are not `#[test]` fns, so opt into the unwrap/expect
//! allowance explicitly (ADR-0017).
#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::time::Duration;

use quiver_proto::v1::{self, quiver_client::QuiverClient};
use quiver_server::{Action, ApiKey, CollectionScope, Config, serve};
use tokio::net::TcpListener;

const ENC_KEY: &str = "00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff";

fn auth_request<T>(secret: &str, message: T) -> tonic::Request<T> {
    let mut request = tonic::Request::new(message);
    request.metadata_mut().insert(
        "authorization",
        format!("Bearer {secret}").parse().expect("valid metadata"),
    );
    request
}

async fn wait_ready(http: &reqwest::Client, base: &str) {
    for _ in 0..200 {
        if let Ok(resp) = http.get(format!("{base}/healthz")).send().await
            && resp.status().is_success()
        {
            return;
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
    panic!("server did not become ready");
}

#[tokio::test]
async fn scoped_keys_deny_over_scope_and_cross_namespace() {
    let tmp = tempfile::tempdir().unwrap();
    let rest_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let grpc_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let rest_addr = rest_listener.local_addr().unwrap();
    let grpc_addr = grpc_listener.local_addr().unwrap();

    // An admin over everything, plus read/write keys scoped to the `acme.`
    // namespace only.
    let acme_only = CollectionScope::Patterns(vec!["acme.*".to_owned()]);
    let config = Config {
        data_dir: tmp.path().to_path_buf(),
        rest_addr,
        grpc_addr,
        api_keys: vec![
            ApiKey::admin("admin-secret"),
            ApiKey {
                secret: "reader-secret".to_owned(),
                role: Action::Read,
                collections: acme_only.clone(),
                id: None,
            },
            ApiKey {
                secret: "writer-secret".to_owned(),
                role: Action::Write,
                collections: acme_only,
                id: None,
            },
        ],
        encryption_key: Some(ENC_KEY.to_owned()),
        tls_cert: None,
        tls_key: None,
        tls_client_ca: None,
        master_key_file: None,
        audit_log: None,
        leader_url: None,
        leader_api_key: None,
        insecure: false,
        limits: quiver_server::Limits::default(),
        embedding: Default::default(),
        rerank: Default::default(),
        rate_limit: Default::default(),
        otlp: Default::default(),
        mvcc_reads: false,
        cluster_shards: Vec::new(),
        cluster_replicas: Vec::new(),
        cluster_shard_key: None,
        coordinator: false,
        coordinator_url: None,
        coordinator_state: None,
        autoscale: Default::default(),
        raft_node_id: None,
        raft_members: Vec::new(),
    };
    let server = tokio::spawn(async move {
        let _ = serve(config, rest_listener, grpc_listener).await;
    });

    let http = reqwest::Client::new();
    let base = format!("http://{rest_addr}");
    wait_ready(&http, &base).await;

    let create = |name: &str, secret: &str| {
        http.post(format!("{base}/v1/collections"))
            .bearer_auth(secret)
            .json(&serde_json::json!({"name": name, "dim": 3, "metric": "l2"}))
            .send()
    };
    let upsert = |name: &str, secret: &str| {
        http.post(format!("{base}/v1/collections/{name}/points"))
            .bearer_auth(secret)
            .json(&serde_json::json!({
                "points": [{"id": "p1", "vector": [0.1, 0.2, 0.3], "payload": {}}]
            }))
            .send()
    };
    let search = |name: &str, secret: &str| {
        http.post(format!("{base}/v1/collections/{name}/query"))
            .bearer_auth(secret)
            .json(&serde_json::json!({"vector": [0.1, 0.2, 0.3], "k": 5}))
            .send()
    };

    // The admin provisions one collection per namespace and seeds a point.
    for name in ["acme.items", "beta.items"] {
        assert_eq!(create(name, "admin-secret").await.unwrap().status(), 200);
        assert_eq!(upsert(name, "admin-secret").await.unwrap().status(), 200);
    }

    // --- In-scope: the reader reads its namespace. ---
    assert_eq!(
        search("acme.items", "reader-secret")
            .await
            .unwrap()
            .status(),
        200
    );
    assert_eq!(
        http.get(format!("{base}/v1/collections/acme.items"))
            .bearer_auth("reader-secret")
            .send()
            .await
            .unwrap()
            .status(),
        200
    );

    // --- Over-scope on the action: a reader cannot write or administer. ---
    assert_eq!(
        upsert("acme.items", "reader-secret")
            .await
            .unwrap()
            .status(),
        403
    );
    assert_eq!(
        create("acme.new", "reader-secret").await.unwrap().status(),
        403
    );
    assert_eq!(
        http.delete(format!("{base}/v1/collections/acme.items"))
            .bearer_auth("reader-secret")
            .send()
            .await
            .unwrap()
            .status(),
        403
    );

    // --- Over-scope on the action: a writer cannot administer. ---
    assert_eq!(
        upsert("acme.items", "writer-secret")
            .await
            .unwrap()
            .status(),
        200
    );
    assert_eq!(
        create("acme.new", "writer-secret").await.unwrap().status(),
        403
    );

    // --- Cross-namespace: acme-scoped keys cannot touch `beta.`. ---
    assert_eq!(
        search("beta.items", "reader-secret")
            .await
            .unwrap()
            .status(),
        403
    );
    assert_eq!(
        http.get(format!("{base}/v1/collections/beta.items"))
            .bearer_auth("reader-secret")
            .send()
            .await
            .unwrap()
            .status(),
        403
    );
    assert_eq!(
        upsert("beta.items", "writer-secret")
            .await
            .unwrap()
            .status(),
        403
    );

    // --- Listing is filtered to the caller's scope. ---
    let listed: serde_json::Value = http
        .get(format!("{base}/v1/collections"))
        .bearer_auth("reader-secret")
        .send()
        .await
        .unwrap()
        .json()
        .await
        .unwrap();
    let names: Vec<&str> = listed
        .as_array()
        .unwrap()
        .iter()
        .map(|c| c["name"].as_str().unwrap())
        .collect();
    assert_eq!(names, ["acme.items"], "the reader must not see beta.items");

    // --- Authentication still gates everything. ---
    assert_eq!(
        http.get(format!("{base}/v1/collections"))
            .send()
            .await
            .unwrap()
            .status(),
        401
    );
    assert_eq!(
        search("acme.items", "wrong-secret").await.unwrap().status(),
        401
    );

    // --- gRPC enforces the same rules: the reader's write is denied, its read
    // allowed. ---
    let mut client = QuiverClient::connect(format!("http://{grpc_addr}"))
        .await
        .unwrap();
    let denied = client
        .upsert(auth_request(
            "reader-secret",
            v1::UpsertRequest {
                collection: "acme.items".to_owned(),
                points: vec![v1::Point {
                    id: "g1".to_owned(),
                    vector: vec![0.1, 0.2, 0.3],
                    payload: b"{}".to_vec(),
                }],
            },
        ))
        .await
        .expect_err("reader must be denied write over gRPC");
    assert_eq!(denied.code(), tonic::Code::PermissionDenied);

    let allowed = client
        .search(auth_request(
            "reader-secret",
            v1::SearchRequest {
                collection: "acme.items".to_owned(),
                vector: vec![0.1, 0.2, 0.3],
                k: 5,
                filter: Vec::new(),
                ef_search: 0,
                with_payload: true,
                with_vector: false,
            },
        ))
        .await;
    assert!(allowed.is_ok(), "reader must be allowed to search in scope");

    server.abort();
}

package quiver

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

// recorded captures what the mock server received.
type recorded struct {
	method string
	path   string
	auth   string
	body   map[string]any
}

// mock returns a server that records the request and replies with respJSON, plus
// a pointer to the last recorded request.
func mock(t *testing.T, status int, respJSON string) (*httptest.Server, *recorded) {
	t.Helper()
	rec := &recorded{}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		rec.method = r.Method
		rec.path = r.URL.Path
		rec.auth = r.Header.Get("Authorization")
		if b, _ := io.ReadAll(r.Body); len(b) > 0 {
			_ = json.Unmarshal(b, &rec.body)
		}
		w.WriteHeader(status)
		_, _ = io.WriteString(w, respJSON)
	}))
	t.Cleanup(srv.Close)
	return srv, rec
}

func TestCreateCollectionSendsDefaultsAndAuth(t *testing.T) {
	srv, rec := mock(t, 200, `{"name":"kb","dim":4,"metric":"l2","count":0}`)
	c := New(srv.URL, WithAPIKey("secret"))
	info, err := c.CreateCollection(context.Background(), "kb", 4, nil)
	if err != nil {
		t.Fatal(err)
	}
	if rec.method != "POST" || rec.path != "/v1/collections" {
		t.Fatalf("got %s %s", rec.method, rec.path)
	}
	if rec.auth != "Bearer secret" {
		t.Fatalf("auth header = %q", rec.auth)
	}
	if rec.body["metric"] != "l2" || rec.body["name"] != "kb" {
		t.Fatalf("body = %v", rec.body)
	}
	if info.Name != "kb" || info.Dim != 4 {
		t.Fatalf("info = %+v", info)
	}
}

func TestUpsertReturnsCount(t *testing.T) {
	srv, rec := mock(t, 200, `{"upserted":2}`)
	c := New(srv.URL)
	n, err := c.Upsert(context.Background(), "kb", []Point{
		{ID: "a", Vector: []float32{1, 0, 0, 0}, Payload: map[string]any{"n": 1}},
		{ID: "b", Vector: []float32{0, 1, 0, 0}},
	})
	if err != nil {
		t.Fatal(err)
	}
	if n != 2 {
		t.Fatalf("upserted = %d", n)
	}
	if rec.path != "/v1/collections/kb/points" {
		t.Fatalf("path = %s", rec.path)
	}
	pts := rec.body["points"].([]any)
	if len(pts) != 2 {
		t.Fatalf("points = %v", pts)
	}
}

func TestSearchAppliesDefaultsAndParsesMatches(t *testing.T) {
	srv, rec := mock(t, 200, `{"matches":[{"id":"a","score":0.5,"payload":{"n":1}},{"id":"b","score":0.9}]}`)
	c := New(srv.URL)
	got, err := c.Search(context.Background(), "kb", []float32{1, 0, 0, 0}, nil)
	if err != nil {
		t.Fatal(err)
	}
